      "severity": "error",
      "method": "automatic",
      "description": "ToolbarとTableを一つのCollectionRegionに置き、検索はHeroUI SearchFieldとしてTable直前の末尾側へ配置する",
      "fix": "Toolbarルートをwidth:100%、display:flex、justify-content:flex-endにし、その中にSearchFieldのGroup、SearchIcon、Input、ClearButtonを置く。SearchFieldはデスクトップ16rem、狭幅100%にする"
    },
    {
      "id": "layout.back-navigation",
      "title": "戻るLinkをページ見出しの前に置く",
      "category": "layout",
      "severity": "error",
      "method": "automatic",
      "description": "親の一覧へ戻るLinkとPageHeadingを一つの見出しグループにまとめ、読む順序と余白を固定する",
      "fix": "BackNavigation、PageHeadingの順に配置し、間をspace.4、PageHeadingから詳細コンテンツまでをspace.8にする。Button固有のpaddingへ位置を依存させない"
    },
    {
      "id": "layout.narrow",
      "title": "狭い画面では1カラムへ積み替える",
      "category": "layout",
      "severity": "error",
      "method": "automatic",
      "description": "320px幅または200% zoomで横スクロールを発生させず、主要情報と操作を欠落させない",
      "fix": "モバイル一覧を縦に積み、詳細画面への移動はLinkとして表示する"
    },
    {
      "id": "state.loading",
      "title": "非同期処理中の状態を示す",
      "category": "state",
      "severity": "error",
      "method": "automatic",
      "description": "保存中であることを示し、二重送信を防ぐ",
      "fix": "Buttonのloadingとdisabledを同期する"
    },
    {
      "id": "state.failure",
      "title": "失敗後も再試行できる",
      "category": "state",
      "severity": "error",
      "method": "ai-review",
      "description": "Toastだけで失敗情報を消さない",
      "fix": "Drawer内にエラーと再試行操作を残す"
    },
    {
      "id": "color.semantic",
      "title": "semantic colorを意味に合わせる",
      "category": "color",
      "severity": "warning",
      "method": "ai-review",
      "description": "危険色を通常操作へ使わない",
      "fix": "操作の意味に対応するtokenへ置き換える"
    }
  ]
}

