{
  "$schema": "../schemas/pattern.schema.json",
  "version": "1.0.0",
  "id": "pattern.page-layout",
  "name": "Page layout",
  "purpose": "業務オブジェクトの関係、重要度、主要操作を、画面をまたいで予測できる順序で配置する",
  "principles": [
    {
      "id": "predictable-order",
      "title": "読む順序を固定する",
      "description": "アプリケーションヘッダー、戻るナビゲーション、ページ見出し、補助ナビゲーション、コンテンツの順に配置する"
    },
    {
      "id": "object-first",
      "title": "業務オブジェクトを起点に選ぶ",
      "description": "一覧、詳細、設定などの画面名ではなく、利用者が比較・確認・切り替えたい対象の関係からvariantを選ぶ"
    },
    {
      "id": "one-primary-action",
      "title": "主要操作を一つに絞る",
      "description": "見出し領域に置く強い操作は一つとし、補助操作は同列に強調しない"
    }
  ],
  "anatomy": [
    {
      "id": "app-header",
      "name": "アプリケーションヘッダー",
      "required": true,
      "description": "サービス全体の移動と利用者コンテキストを提供する"
    },
    {
      "id": "back-navigation",
      "name": "戻るナビゲーション",
      "required": false,
      "description": "親の一覧や上位ビューへ戻る経路がある詳細画面では、ページ見出しの前に配置する"
    },
    {
      "id": "page-heading",
      "name": "ページ見出し",
      "required": true,
      "description": "画面タイトル、短いリード文、状態、主要操作をまとめる"
    },
    {
      "id": "local-navigation",
      "name": "補助ナビゲーション",
      "required": false,
      "description": "同じ業務オブジェクト内で頻繁に表示を切り替える場合だけ追加する"
    },
    {
      "id": "content",
      "name": "コンテンツ領域",
      "required": true,
      "description": "情報をセクションへ分け、重要度の高い順に配置する"
    },
    {
      "id": "feedback",
      "name": "フィードバック領域",
      "required": false,
      "description": "読み込み、空、失敗、権限制限を操作対象の近くに表示する"
    }
  ],
  "variants": [
    {
      "id": "collection-table",
      "name": "一覧（テーブル）",
      "useWhen": "複数のオブジェクトを属性で比較しながら探す",
      "avoidWhen": "項目数が少ない、または狭い画面での利用が中心",
      "structure": ["ページ見出し", "一覧操作Toolbar", "テーブル", "ページネーション"],
      "desktop": "コンテンツ幅を広く使い、比較に必要な列を優先して表示する",
      "narrow": "一覧（リスト）へ切り替え、主要属性以外は詳細画面へ移す",
      "layout": {
        "breakpoint": "breakpoint.narrow",
        "classes": [
          ".page-shell",
          ".page-shell--stack",
          ".page-heading",
          ".collection-region",
          ".collection-toolbar",
          ".search-field",
          ".collection-table-wrap",
          ".collection-list-mobile"
        ],
        "values": {
          "maxWidth": "content.maxWidth",
          "pagePaddingBlock": "space.8",
          "toolbarGapBeforeTable": "space.3",
          "headingToCollectionGap": "space.6",
          "searchDesktopWidth": "16rem",
          "searchNarrowWidth": "100%"
        }
      }
    },
    {
      "id": "collection-list",
      "name": "一覧（リスト）",
      "useWhen": "狭い領域でオブジェクトの識別情報と状態を順番に確認する",
      "avoidWhen": "複数列を横断して比較することが主要タスク",
      "structure": ["ページ見出し", "検索・絞り込み", "リスト", "追加読み込み"],
      "desktop": "短い一覧や補助領域で使用し、必要以上にカード化しない",
      "narrow": "1行に識別情報、状態、主要操作を置き、詳細は次画面に分ける",
      "layout": {
        "breakpoint": "breakpoint.narrow",
        "classes": [
          ".collection-list-mobile",
          ".collection-list-mobile__content",
          ".collection-list-mobile__link",
          ".collection-list-mobile__meta"
        ],
        "values": {
          "itemGap": "space.4",
          "contentGap": "space.3"
        }
      }
    },
    {
      "id": "single-one-column",
      "name": "詳細（1カラム）",
      "useWhen": "一つのオブジェクトを、並列な情報セクションに分けて確認・操作する",
      "avoidWhen": "複数のオブジェクトを横断して比較・探索することが主要タスク",
      "structure": ["戻るナビゲーション", "ページ見出し", "概要", "詳細セクション", "関連オブジェクト"],
      "desktop": "最大1200pxの中で、セクションを重要度順に縦へ配置する",
      "narrow": "モバイルでは1カラムに積み替える",
      "layout": {
        "breakpoint": "breakpoint.narrow",
        "classes": [
          ".page-shell",
          ".page-shell--stack",
          ".detail-page__heading",
          ".page-heading",
          ".detail-grid",
          ".detail-content"
        ],
        "values": {
          "maxWidth": "content.maxWidth",
          "backNavigationGap": "space.4",
          "headingToContentGap": "space.8",
          "sectionGap": "space.6",
          "groupGap": "space.4"
        }
      }
    }
  ],
  "states": ["loading", "empty", "error", "permission-limited"],
  "components": [
    "component.button",
    "component.link",
    "component.table",
    "component.toolbar",
    "component.search-field",
    "component.card",
    "component.chip",
    "component.surface"
  ],
  "rules": [
    "layout.grouping",
    "layout.collection-toolbar",
    "layout.back-navigation",
    "layout.narrow",
    "a11y.control-name",
    "a11y.color-only",
    "navigation.link-semantics",
    "color.semantic"
  ]
}
=== spacing-layout.json ===
{
  "$schema": "../schemas/pattern.schema.json",
  "version": "1.0.0",
  "id": "pattern.spacing-layout",
  "name": "余白の取り方",
  "purpose": "要素同士の関係と情報の階層を、Atlasの余白トークンで一貫して表現する",
  "principles": [
    {
      "id": "proximity-shows-relationship",
      "title": "関係が近いほど余白を小さくする",
      "description": "同じ情報のまとまりは近づけ、目的が異なるまとまりは広く離して、読む前から関係を判断できるようにする"
    },
    {
      "id": "outside-to-inside",
      "title": "外側から内側へ段階的に狭くする",
      "description": "ページ、セクション、グループ、要素の順に余白を小さくし、視線を大きなまとまりから詳細へ導く"
    },
    {
      "id": "token-only",
      "title": "定義済みトークンから選ぶ",
      "description": "見た目に合わせた任意の数値は増やさず、space.1からspace.12の意味と近い値を選ぶ"
    }
  ],
  "anatomy": [
    {
      "id": "page-padding",
      "name": "ページの内側余白",
      "required": true,
      "description": "デスクトップはspace.8（32px）、狭い画面は上下space.6（24px）・左右space.4（16px）を基準にする"
    },
    {
      "id": "section-gap",
      "name": "セクション間",
      "required": true,
      "description": "目的が異なる情報のまとまりをspace.8（32px）で分ける"
    },
    {
      "id": "group-gap",
      "name": "セクション内のグループ間",
      "required": true,
      "description": "関連する情報群をspace.6（24px）で分ける"
    },
    {
      "id": "element-gap",
      "name": "見出し・要素間",
      "required": true,
      "description": "見出しと内容はspace.4（16px）、アイコンと文字など強く関連する要素はspace.1〜space.2（4〜8px）を使う"
    }
  ],
  "variants": [
    {
      "id": "page-content",
      "name": "ページとセクション",
      "useWhen": "ページ全体と、その中にある複数の情報セクションを配置する",
      "avoidWhen": "コンポーネント内部だけの局所的な配置を調整する",
      "structure": ["ページ内側 space.8", "セクション間 space.8", "グループ間 space.6", "見出しと内容 space.4"],
      "desktop": "外周32px、セクション間32px、グループ間24px、見出しと内容16px",
      "narrow": "外周を上下24px・左右16pxに縮め、内容間の余白は原則として維持する",
      "layout": {
        "breakpoint": "breakpoint.narrow",
        "classes": [".page-shell", ".page-shell--stack"],
        "values": {
          "pagePadding": "space.8",
          "sectionGap": "space.8",
          "groupGap": "space.6",
          "headingGap": "space.4",
          "narrowPagePaddingBlock": "space.6",
          "narrowPagePaddingInline": "space.4"
        }
      }
    },
    {
      "id": "surface-content",
      "name": "サーフェスの内側",
      "useWhen": "CardやSurfaceの枠が一つの情報のまとまりを表す",
      "avoidWhen": "余白だけでまとまりを十分に示せるため、枠自体が不要な場合",
      "structure": ["内側 space.6", "グループ間 space.4", "要素間 space.2"],
      "desktop": "内側24px、グループ間16px、強く関連する要素間8px",
      "narrow": "内側を16pxに縮め、グループ間16pxと要素間8pxは維持する",
      "layout": {
        "breakpoint": "breakpoint.narrow",
        "values": {
          "padding": "space.6",
          "groupGap": "space.4",
          "elementGap": "space.2",
          "narrowPadding": "space.4"
        }
      }
    },
    {
      "id": "dialog-content",
      "name": "ダイアログの内側",
      "useWhen": "確認や入力の内容を、説明・フォーム・操作の順に配置する",
      "avoidWhen": "常時参照する情報や、複数画面にまたがる長い操作を収める",
      "structure": ["内側 space.6", "説明とフォーム space.8", "フォーム間 space.6", "ラベルと入力 space.2"],
      "desktop": "内側24px、説明とフォーム32px、フォーム間24px、ラベルと入力8px",
      "narrow": "内側を16pxに縮め、内容同士の関係を示す余白は維持する",
      "layout": {
        "breakpoint": "breakpoint.narrow",
        "classes": [".drawer-form"],
        "values": {
          "padding": "space.6",
          "introToFormGap": "space.8",
          "formGap": "space.6",
          "labelGap": "space.2",
          "narrowPadding": "space.4"
        }
      }
    },
    {
      "id": "inline-actions",
      "name": "横並びの要素",
      "useWhen": "アイコンと文字、状態とラベル、複数の操作を横に並べる",
      "avoidWhen": "狭い画面で折り返すと操作順序や対応関係が崩れる",
      "structure": ["アイコンと文字 space.1〜2", "ボタン間 space.2〜4", "入力欄間 space.4"],
      "desktop": "アイコンと文字4〜8px、ボタン間8〜16px、入力欄間16px",
      "narrow": "同じ値を維持する。幅が足りない場合は余白を削らず縦に積み替える",
      "layout": {
        "values": {
          "iconGap": "space.1",
          "buttonGap": "space.2",
          "fieldGap": "space.4"
        }
      }
    }
  ],
