                <Drawer.Content className="record-drawer" placement="right">
                  <Drawer.Dialog>
                    <Drawer.CloseTrigger aria-label="閉じる" />
                    <Form validationBehavior="aria" onSubmit={handleSave}>
                      <Drawer.Header>
                        <Drawer.Heading>顧客情報の編集</Drawer.Heading>
                      </Drawer.Header>
                      <Drawer.Body>
                        <div className="drawer-form">
