                                </Alert.Description>
                              </Alert.Content>
                            </Alert>
                          )}
                          <CustomerFormFields
                            errors={fieldErrors}
                            isDisabled={isSaving}
                            values={values}
                            onChange={setValues}
                          />
                        </div>
                      </Drawer.Body>
                      <Drawer.Footer>
                        <Button
