                          variant="tertiary"
                          onPress={() => handleEditOpenChange(false)}
                        >
                          キャンセル
                        </Button>
                        <Button isDisabled={isSaving} isPending={isSaving} type="submit" variant="primary">
                          保存する
                        </Button>
                      </Drawer.Footer>
                    </Form>
                  </Drawer.Dialog>
                </Drawer.Content>
              </Drawer.Backdrop>
            </Drawer>

            <AlertDialog isOpen={isDeleteOpen} onOpenChange={setIsDeleteOpen}>
