type ColumnId = "companyName" | "contactName" | "lastContactedAt" | "status";

type CustomerColumn = {
  id: ColumnId;
  label: string;
  width: string;
  minWidth: number;
  align: "start" | "end";
  isRowHeader: boolean;
  tabular: boolean;
};

